import { FDOInterface, FDO_SDK, PluginMetadata } from "@anikitenko/fdo-sdk";
import type { RenderOnLoadModule } from "@anikitenko/fdo-sdk";
import css from "./styles.css";
import { renderComposed } from "./render";
import { buildRenderOnLoadActions } from "./ui/actions";

class WebToolsWorkbenchPlugin extends FDO_SDK implements FDOInterface {
  private readonly _metadata: PluginMetadata = {
    name: "Web Tools Workbench",
    version: "1.0.0",
    author: "Web Tools Workbench",
    description: "A local, browser-only webmaster toolkit: formatting, text, SEO, images, and social previews.",
    icon: "applications",
  };

  get metadata(): PluginMetadata {
    return this._metadata;
  }

  init(): void {
    this.info("Web Tools Workbench initialized");
  }

  render(): string {
    return renderComposed(css as Record<string, Record<string, string>>);
  }

  renderOnLoad(): RenderOnLoadModule {
    return buildRenderOnLoadActions();
  }
}

export default WebToolsWorkbenchPlugin;
new WebToolsWorkbenchPlugin();

