import type { DOM } from "@anikitenko/fdo-sdk";
import { renderDashboard } from "./ui/dashboard";
import { renderLibrary } from "./ui/library";
import { renderSpace } from "./ui/space";
import { renderJsonWorkspace } from "./ui/json-workspace";
import { renderTextWorkspace } from "./features/text/render";
import { renderDataWorkspace } from "./features/data/render";
import { renderSeoWorkspace } from "./features/seo/render";
import { renderImagesWorkspace } from "./features/images/render";
import { renderSocialWorkspace } from "./features/social/render";

interface CssMap {
  [key: string]: Record<string, string>;
}

export interface RenderComposedOptions {
  dom: DOM;
  css: CssMap;
}

export function renderComposed(opts: RenderComposedOptions): string {
  const { dom, css } = opts;

  const shellClass = dom.createClassFromStyle(css["shell"]);
  const dashboardClass = dom.createClassFromStyle(css["dashboard"]);
  const cardClass = dom.createClassFromStyle(css["card"]);
  const libraryClass = dom.createClassFromStyle(css["library"]);
  const workspaceClass = dom.createClassFromStyle(css["workspace"]);
  const resultClass = dom.createClassFromStyle(css["result"]);
  const dockClass = dom.createClassFromStyle(css["dock"]);

  const dashboard = renderDashboard({ dom, css, dashboardClass, cardClass });
  const library = renderLibrary({ dom, css, libraryClass, cardClass });
  const space = renderSpace({ dom, css });
  const jsonWorkspace = renderJsonWorkspace({
    dom,
    css,
    workspaceClass,
    cardClass,
    resultClass,
  });

  const textWorkspace = renderTextWorkspace({
    dom,
    css,
    categoryShellClass: workspaceClass,
    categoryInputClass: cardClass,
    categoryActionClass: cardClass,
    categoryResultClass: resultClass,
    categoryBackClass: cardClass,
  });

  const dataWorkspace = renderDataWorkspace({
    dom,
    css,
    categoryShellClass: workspaceClass,
    categoryInputClass: cardClass,
    categoryActionClass: cardClass,
    categoryResultClass: resultClass,
    categoryBackClass: cardClass,
  });

  const seoWorkspace = renderSeoWorkspace({
    dom,
    css,
    categoryShellClass: workspaceClass,
    categoryInputClass: cardClass,
    categoryActionClass: cardClass,
    categoryResultClass: resultClass,
    categoryBackClass: cardClass,
  });

  const imagesWorkspace = renderImagesWorkspace({
    dom,
    css,
    categoryShellClass: workspaceClass,
    categoryInputClass: cardClass,
    categoryActionClass: cardClass,
    categoryResultClass: resultClass,
    categoryBackClass: cardClass,
  });

  const socialWorkspace = renderSocialWorkspace({
    dom,
    css,
  });

  const shell = dom.createElement(
    "div",
    { class: shellClass, "data-role": "tool-workbench" },
    [
      dom.createElement("div", { class: dashboardClass, "data-role": "tool-dashboard" }, [
        dashboard,
      ]),
      dom.createElement("div", { class: libraryClass, "data-role": "tool-library", "data-state": "closed" }, [
        library,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-workspace", style: "display:none" }, [
        jsonWorkspace,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-category-workspace", "data-tool-category": "text", style: "display:none" }, [
        textWorkspace,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-category-workspace", "data-tool-category": "data", style: "display:none" }, [
        dataWorkspace,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-category-workspace", "data-tool-category": "seo", style: "display:none" }, [
        seoWorkspace,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-category-workspace", "data-tool-category": "images", style: "display:none" }, [
        imagesWorkspace,
      ]),
      dom.createElement("div", { class: workspaceClass, "data-role": "tool-category-workspace", "data-tool-category": "social", style: "display:none" }, [
        socialWorkspace,
      ]),
      dom.createElement("div", { class: dockClass, "data-role": "tool-dock" }),
    ]
  );

  const spaceOverlay = dom.createElement(
    "div",
    { class: workspaceClass, "data-role": "tool-space-dialog", "data-state": "closed", style: "display:none" },
    [space]
  );

  return dom.renderHTML(
    dom.createElement("div", { class: shellClass }, [shell, spaceOverlay])
  );
}

