/**
 * Pure Text & Content tool logic.
 * No DOM access; deterministic string transformations and counts.
 */

export type TextTransformMode = "upper" | "lower" | "title";

export interface TextTransformResult {
  transformed: string;
  charCount: number;
  wordCount: number;
}

/** Convert every word to the leading character uppercased and the remainder lowercase. */
export function titleCase(text: string): string {
  return text.replace(/\S+/g, (word) => {
    const first = word.charAt(0);
    const rest = word.slice(1);
    return first.toUpperCase() + rest.toLowerCase();
  });
}

/**
 * Apply the requested transformation to the supplied text.
 * Returns the transformed text along with character and word counts.
 * An empty/whitespace-only input yields an empty transformed string and zero counts.
 */
export function transformText(
  text: string,
  mode: TextTransformMode
): TextTransformResult {
  let transformed: string;
  switch (mode) {
    case "upper":
      transformed = text.toUpperCase();
      break;
    case "lower":
      transformed = text.toLowerCase();
      break;
    case "title":
      transformed = titleCase(text);
      break;
    default:
      transformed = text;
  }
  const trimmed = transformed.trim();
  const charCount = transformed.length;
  const wordCount = trimmed.length === 0 ? 0 : trimmed.split(/\s+/).length;
  return { transformed, charCount, wordCount };
}

/**
 * Count words by whitespace-delimited runs; an empty/whitespace-only string is zero.
 */
export function countWords(text: string): number {
  const trimmed = text.trim();
  return trimmed.length === 0 ? 0 : trimmed.split(/\s+/).length;
}

/**
 * Count characters in the exact (untrimmed) input; empty input is zero.
 */
export function countChars(text: string): number {
  return text.length;
}

