import type { DOM } from "@anikitenko/fdo-sdk";

interface CssMap {
  [key: string]: Record<string, string>;
}

export interface TextWorkspaceRenderOptions {
  dom: DOM;
  css: CssMap;
  categoryShellClass?: string;
  categoryInputClass?: string;
  categoryActionClass?: string;
  categoryResultClass?: string;
  categoryBackClass?: string;
}

/**
 * Render the Text & Content category workspace.
 *
 * Emits the shared category workspace shell markup with the text-specific
 * labelled select (upper / lower / title) and the standard
 * input / action / result / back roles required by the workbench.
 */
export function renderTextWorkspace(opts: TextWorkspaceRenderOptions): string {
  const { dom, css, categoryShellClass, categoryInputClass, categoryActionClass, categoryResultClass, categoryBackClass } = opts;

  const shellCls = categoryShellClass ?? dom.createClassFromStyle(css["category-shell"] ?? {});
  const inputCls = categoryInputClass ?? dom.createClassFromStyle(css["category-input"] ?? {});
  const actionCls = categoryActionClass ?? dom.createClassFromStyle(css["category-action"] ?? {});
  const resultCls = categoryResultClass ?? dom.createClassFromStyle(css["category-result"] ?? {});
  const backCls = categoryBackClass ?? dom.createClassFromStyle(css["category-back"] ?? {});

  const selectHtml = dom.createElement(
    "select",
    {
      id: "text-transform-select",
      name: "transform",
      class: "pure-input",
      "aria-label": "Text transformation",
    },
    [
      dom.createElement("option", { value: "upper" }, "Uppercase"),
      dom.createElement("option", { value: "lower" }, "Lowercase"),
      dom.createElement("option", { value: "title" }, "Title case"),
    ]
  );

  const labelHtml = dom.createElement(
    "label",
    { for: "text-transform-select", class: "category-select-label" },
    "Transformation"
  );

  const inputHtml = dom.createElement(
    "textarea",
    {
      id: "text-category-input",
      name: "text-input",
      "data-role": "tool-category-input",
      class: `pure-input ${inputCls}`.trim(),
      placeholder: "Paste or type text to transform\u2026",
      rows: 6,
      "aria-label": "Text input",
    }
  );

  const actionHtml = dom.createElement(
    "button",
    {
      type: "button",
      "data-role": "tool-category-action",
      class: `pure-button pure-button-primary ${actionCls}`.trim(),
      "aria-label": "Run text transformation",
    },
    "Run"
  );

  const resultHtml = dom.createElement(
    "pre",
    {
      id: "text-category-result",
      "data-role": "tool-category-result",
      "data-state": "idle",
      class: resultCls,
      "aria-label": "Transformation result",
    },
    "Result will appear here\u2026"
  );

  const backHtml = dom.createElement(
    "button",
    {
      type: "button",
      "data-role": "tool-category-back",
      class: `pure-button ${backCls}`.trim(),
      "aria-label": "Back to dashboard",
    },
    "\u2190 Back"
  );

  return dom.createElement(
    "div",
    {
      "data-role": "tool-category-workspace",
      "data-tool-category": "text",
      class: shellCls,
    },
    [
      backHtml,
      dom.createElement("h2", { class: "category-title" }, "Text & Content"),
      dom.createElement("p", { class: "category-subtitle" }, "Transform text and inspect character/word counts locally."),
      labelHtml,
      selectHtml,
      inputHtml,
      actionHtml,
      resultHtml,
    ]
  );
}

/features/text/actions.ts:
import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";

const HANDLERS = {
  textAction: ({ document }: { document: Document }) => {
    const select = document.querySelector<HTMLSelectElement>('[data-role="tool-text-mode"]');
    const input = document.querySelector<HTMLTextAreaElement>('[data-role="tool-category-input"]');
    const result = document.querySelector<HTMLElement>('[data-role="tool-category-result"]');
    if (!select || !input || !result) return;

    const text = input.value;
    const mode = (select.value || "upper") as "upper" | "lower" | "title";

    if (!text.trim()) {
      result.dataset.state = "error";
      result.textContent = "Please enter some text to transform.";
      return;
    }

    const words = text.trim().split(/\s+/).filter(Boolean).length;
    const chars = text.length;

    let transformed: string;
    if (mode === "upper") {
      transformed = text.toUpperCase();
    } else if (mode === "lower") {
      transformed = text.toLowerCase();
    } else {
      transformed = text
        .toLowerCase()
        .replace(/(^|\s)\S/g, (m) => m.toUpperCase());
    }

    result.dataset.state = "success";
    result.textContent = `${transformed}\n\nCharacters: ${chars} | Words: ${words}`;
  },
  textBack: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "";
    if (workspace) workspace.style.display = "none";
  },
} as const;

const BINDINGS = [
  {
    selector: '[data-role="tool-category-action"]',
    event: "click",
    handler: HANDLERS.textAction,
    preventDefault: true,
  },
  {
    selector: '[data-role="tool-category-back"]',
    event: "click",
    handler: HANDLERS.textBack,
    preventDefault: true,
  },
] as const;

export function buildTextActions() {
  return defineRenderOnLoadActions({
    handlers: HANDLERS,
    bindings: [...BINDINGS],
    description: "Text & Content workspace actions",
  });
}

/features/data/logic.ts:
export type DataOperation = "json" | "encode" | "decode";

export interface DataOperationResult {
  success: boolean;
  output: string;
  message?: string;
}

export function formatJson(input: string): DataOperationResult {
  const trimmed = input.trim();
  if (!trimmed) {
    return { success: false, output: "", message: "Please enter JSON to format." };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch (err) {
    const reason = err instanceof Error ? err.message : "Invalid JSON";
    return {
      success: false,
      output: "",
      message: `Invalid JSON: ${reason}`,
    };
  }

  return {
    success: true,
    output: JSON.stringify(parsed, null, 2),
  };
}

export function encodeUrlQuery(input: string): DataOperationResult {
  if (!input.trim()) {
    return { success: false, output: "", message: "Please enter text to encode." };
  }
  return { success: true, output: encodeURIComponent(input) };
}

export function decodeUrlQuery(input: string): DataOperationResult {
  if (!input.trim()) {
    return { success: false, output: "", message: "Please enter encoded text to decode." };
  }
  try {
    return { success: true, output: decodeURIComponent(input) };
  } catch {
    return {
      success: false,
      output: "",
      message: "Unable to decode: input is not a valid URI-encoded string.",
    };
  }
}

export function runDataOperation(
  input: string,
  operation: DataOperation
): DataOperationResult {
  switch (operation) {
    case "json":
      return formatJson(input);
    case "encode":
      return encodeUrlQuery(input);
    case "decode":
      return decodeUrlQuery(input);
  }
}

