  const inputClass = opts.categoryInputClass ?? dom.createClassFromStyle({ width: "100%" });
  const actionClass = opts.categoryActionClass ?? dom.createClassFromStyle({ display: "inline-block" });
  const resultClass = opts.categoryResultClass ?? dom.createClassFromStyle({ display: "block" });
  const backClass = opts.categoryBackClass ?? dom.createClassFromStyle({ display: "inline-block" });

  const formClass = dom.createClassFromStyle({
    display: "block",
    marginBottom: "16px",
  });

  const selectWrapClass = dom.createClassFromStyle({
    display: "block",
    marginBottom: "12px",
  });

  const labelClass = dom.createClassFromStyle({
    display: "block",
    marginBottom: "4px",
    fontSize: "13px",
    color: "#555",
  });

