  const backButtonClass = dom.createClassFromStyle({
    padding: "8px 16px",
    fontSize: "14px",
    background: "transparent",
    border: "1px solid #999",
    borderRadius: "4px",
    cursor: "pointer",
    marginBottom: "16px",
  });

  const actionButtonClass = dom.createClassFromStyle({
    padding: "10px 24px",
    fontSize: "14px",
    background: "#1a3a3a",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    marginTop: "12px",
  });

  const resultWrapClass = dom.createClassFromStyle({
    marginTop: "16px",
  });

  const resultInnerClass = dom.createClassFromStyle({
    padding: "12px",
    fontSize: "13px",
    fontFamily: "monospace",
    background: "#f9f9f9",
    border: "1px solid #ddd",
    borderRadius: "4px",
    minHeight: "60px",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  });

  const parts: string[] = [];

  parts.push(
    dom.createElement(
