        dom.createElement("div", { class: headingClass }, [
          dom.createElement("span", {}, ["Development & Data"]),
        ]),
        dom.createElement("div", { class: subtitleClass }, [
          dom.createElement("span", {}, ["Format JSON or encode/decode URL query text locally."]),
