            dom.createElement("select", {
              id: "tool-data-mode",
              "data-role": "tool-data-mode",
              class: selectClass,
            }, [
              dom.createElement("option", { value: "json" }, ["JSON Formatter"]),
              dom.createElement("option", { value: "encode" }, ["URL Encode"]),
              dom.createElement("option", { value: "decode" }, ["URL Decode"]),
            ]),
          ]),

          dom.createElement("div", {}, [
            dom.createElement("label", { class: inputLabelClass, for: "tool-data-input" }, [
              dom.createElement("span", {}, ["Input"]),
            ]),
            dom.createElement("textarea", {
              id: "tool-data-input",
              "data-role": "tool-category-input",
              class: textareaClass,
              placeholder: 'Paste JSON, text to encode, or URI-encoded string to decode…',
            }, []),
