          }, [
            dom.createElement("div", { class: resultInnerClass }, [
              dom.createElement("span", {}, ["Result will appear here…"]),
            ]),
          ]),
        ]),
      ]
    )
  );

  return parts.join("\n");
}

/features/data/actions.ts:
import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";

const HANDLERS = {
  dataAction: ({ document }: { document: Document }) => {
    const select = document.querySelector<HTMLSelectElement>('[data-role="tool-data-mode"]');
    const input = document.querySelector<HTMLTextAreaElement>('[data-role="tool-category-input"]');
    const result = document.querySelector<HTMLElement>('[data-role="tool-category-result"]');
    if (!select || !input || !result) return;

    const operation = (select.value || "json") as "json" | "encode" | "decode";
    const text = input.value;

    if (!text.trim()) {
      result.dataset.state = "error";
      result.textContent =
        operation === "json"
          ? "Please enter JSON to format."
          : "Please enter text to process.";
      return;
    }

    if (operation === "json") {
      let parsed: unknown;
      try {
        parsed = JSON.parse(text);
      } catch (err) {
        const reason = err instanceof Error ? err.message : "Invalid JSON";
        result.dataset.state = "error";
        result.textContent = `Invalid JSON: ${reason}`;
        return;
      }
      result.dataset.state = "success";
      result.textContent = JSON.stringify(parsed, null, 2);
    } else if (operation === "encode") {
      result.dataset.state = "success";
      result.textContent = encodeURIComponent(text);
    } else {
      try {
        result.dataset.state = "success";
        result.textContent = decodeURIComponent(text);
      } catch {
        result.dataset.state = "error";
        result.textContent = "Unable to decode: input is not a valid URI-encoded string.";
      }
    }
  },
  dataBack: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "";
    if (workspace) workspace.style.display = "none";
  },
} as const;

const BINDINGS = [
  {
    selector: '[data-role="tool-category-action"]',
    event: "click",
    handler: HANDLERS.dataAction,
    preventDefault: true,
  },
  {
    selector: '[data-role="tool-category-back"]',
    event: "click",
    handler: HANDLERS.dataBack,
    preventDefault: true,
  },
] as const;

export function buildDataActions() {
  return defineRenderOnLoadActions({
    handlers: HANDLERS,
    bindings: [...BINDINGS],
    description: "Development & Data workspace actions",
  });
}

/features/seo/logic.ts:
export interface SeoHeading {
  level: number;
  text: string;
}

export interface SeoLink {
  href: string;
  text: string;
}

export interface SeoImage {
  src: string;
  alt: string | null;
  hasAlt: boolean;
}

export interface SeoAnalysisResult {
  success: boolean;
  message?: string;
  title?: { present: boolean; text: string; length: number };
  description?: { present: boolean; text: string; length: number };
  headings?: SeoHeading[];
  links?: SeoLink[];
  images?: SeoImage[];
  imageAltCoverage?: { total: number; withAlt: number; percent: number };
}

function decodeEntities(input: string): string {
  return input
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)));
}

function extractTagContent(html: string, tag: string): string | null {
  const open = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, "i");
  const match = html.match(open);
  return match ? decodeEntities(match[1].trim()) : null;
}

function extractTagAttribute(html: string, tag: string, attr: string): string | null {
  const open = new RegExp(`<${tag}[^>]*\\b${attr}\\s*=\\s*("([^"]*)"|'([^']*)')`, "i");
  const match = html.match(open);
  if (!match) return null;
  return decodeEntities(match[2] ?? match[3] ?? "");
}

function extractHeadings(html: string): SeoHeading[] {
  const headings: SeoHeading[] = [];
  const regex = /<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(html)) !== null) {
    const level = Number(match[1]);
    const text = decodeEntities(match[2].replace(/<[^>]+>/g, "").trim());
    headings.push({ level, text });
  }
  return headings;
}

function extractLinks(html: string): SeoLink[] {
  const links: SeoLink[] = [];
  const regex = /<a[^>]*\bhref\s*=\s*("([^"]*)"|'([^']*)')[^>]*>([\s\S]*?)<\/a>/gi;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(html)) !== null) {
    const href = decodeEntities(match[2] ?? match[3] ?? "");
    const text = decodeEntities(match[4].replace(/<[^>]+>/g, "").trim());
    links.push({ href, text });
  }
  return links;
}

function extractImages(html: string): SeoImage[] {
  const images: SeoImage[] = [];
  const regex = /<img\b[^>]*>/gi;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(html)) !== null) {
    const tag = match[0];
    const srcMatch = tag.match(/\bsrc\s*=\s*("([^"]*)"|'([^']*)')/i);
    const altMatch = tag.match(/\balt\s*=\s*("([^"]*)"|'([^']*)')/i);
    const src = srcMatch ? decodeEntities(srcMatch[2] ?? srcMatch[3] ?? "") : "";
    const alt = altMatch ? decodeEntities(altMatch[2] ?? altMatch[3] ?? "") : null;
    const hasAlt = alt !== null && alt.trim().length > 0;
    images.push({ src, alt, hasAlt });
  }
  return images;
}

export function analyzeHtml(html: string): SeoAnalysisResult {
  const trimmed = html.trim();
  if (!trimmed) {
    return {
      success: false,
      message: "Please paste some HTML to analyze.",
    };
  }

  const titleText = extractTagContent(html, "title") ?? "";
  const descText = extractTagAttribute(html, "meta", "content") &&
    /<meta[^>]*\bname\s*=\s*("description"|'description')[^>]*>/i.test(html)
      ? extractMetaDescription(html)
      : "";

  const title = {
    present: titleText.length > 0,
    text: titleText,
    length: titleText.length,
  };
  const description = {
    present: (descText ?? "").length > 0,
    text: descText ?? "",
    length: (descText ?? "").length,
  };
  const headings = extractHeadings(html);
  const links = extractLinks(html);
  const images = extractImages(html);

  const totalImages = images.length;
  const withAlt = images.filter((img) => img.hasAlt).length;
  const imageAltCoverage = {
    total: totalImages,
    withAlt,
    percent: totalImages === 0 ? 100 : Math.round((withAlt / totalImages) * 100),
  };

  return {
    success: true,
    title,
    description,
    headings,
    links,
    images,
    imageAltCoverage,
  };
}

function extractMetaDescription(html: string): string {
  const regex = /<meta[^>]*\bname\s*=\s*("description"|'description')[^>]*\bcontent\s*=\s*("([^"]*)"|'([^']*)')/i;
  const match = html.match(regex);
  if (!match) return "";
  return decodeEntities(match[3] ?? match[4] ?? "");
}

