/features/seo/actions.ts:
import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";

const HANDLERS = {
  seoAction: ({ document }: { document: Document }) => {
    const input = document.querySelector<HTMLTextAreaElement>(
      '[data-role="tool-category-input"]'
    );
    const result = document.querySelector<HTMLElement>(
      '[data-role="tool-category-result"]'
    );
    if (!input || !result) return;

    const html = input.value;
    if (!html.trim()) {
      result.dataset.state = "error";
      result.textContent = "Please paste some HTML to analyze.";
      return;
    }

    const extract = (pattern: RegExp, contentPattern: RegExp): {
      present: boolean;
      text: string;
      length: number;
    } => {
      const match = html.match(pattern);
      if (!match) return { present: false, text: "", length: 0 };
      const text = contentPattern.exec(match[0])?.[1] ?? "";
      return { present: text.length > 0, text, length: text.length };
    };

    const title = extract(
      /<title[^>]*>([\s\S]*?)<\/title>/i,
      /<title[^>]*>([\s\S]*?)<\/title>/i
    );
    const description = extract(
      /<meta\s+[^>]*name\s*=\s*["']description["'][^>]*content\s*=\s*["']([^"']*)["']|<meta\s+[^>]*content\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']description["']/i,
      /<meta\s+[^>]*name\s*=\s*["']description["'][^>]*content\s*=\s*["']([^"']*)["']|<meta\s+[^>]*content\s*=\s*["']([^"']*)["'][^>]*name\s*=\s*["']description["']/i
    );

    const headingMatch = html.match(/<h([1-6])[^>]*>([\s\S]*?)<\/h[1-6]>/gi);
    const headings: { level: number; text: string }[] = [];
    if (headingMatch) {
      for (const h of headingMatch) {
        const m = h.match(/^<h([1-6])[^>]*>([\s\S]*?)<\/h[1-6]>/i);
        if (m) {
          headings.push({
            level: parseInt(m[1], 10),
            text: m[2].replace(/<[^>]*>/g, "").trim(),
          });
        }
      }
    }

    const linkMatch = html.match(/<a\s+[^>]*href\s*=\s*["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi);
    const links: { href: string; text: string }[] = [];
    if (linkMatch) {
      for (const l of linkMatch) {
        const m = l.match(
          /^<a\s+[^>]*href\s*=\s*["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/i
        );
        if (m) {
          links.push({
            href: m[1],
            text: m[2].replace(/<[^>]*>/g, "").trim(),
          });
        }
      }
    }

    const imgMatch = html.match(/<img\s+[^>]*\/?>/gi);
    let images: { src: string; hasAlt: boolean }[] = [];
    let altCount = 0;
    if (imgMatch) {
      for (const img of imgMatch) {
        const srcMatch = img.match(/src\s*=\s*["']([^"']*)["']/i);
        const altMatch = img.match(/alt\s*=\s*["']([^"']*)["']/i);
        const hasAlt = altMatch !== null && altMatch[1].trim() !== "";
        if (hasAlt) altCount++;
        images.push({ src: srcMatch ? srcMatch[1] : "", hasAlt });
      }
    }
    const total = images.length;
    const percent = total > 0 ? Math.round((altCount / total) * 100) : 0;

    const lines: string[] = [];
    lines.push(`Title: ${title.present ? `"${title.text}" (${title.length} chars)` : "missing"}`);
    lines.push(
      `Description: ${description.present ? `"${description.text}" (${description.length} chars)` : "missing"}`
    );
    lines.push(`Headings: ${headings.length} found`);
    if (headings.length > 0) {
      for (const h of headings.slice(0, 10)) {
        lines.push(`  H${h.level}: ${h.text}`);
      }
      if (headings.length > 10) lines.push(`  ... and ${headings.length - 10} more`);
    }
    lines.push(`Links: ${links.length} found`);
    lines.push(
      `Images: ${total} total, ${altCount} with alt (${percent}% coverage)`
    );

    result.dataset.state = "success";
    result.textContent = lines.join("\n");
  },
  seoBack: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>(
      '[data-role="tool-dashboard"]'
    );
    const workspace = document.querySelector<HTMLElement>(
      '[data-role="tool-category-workspace"]'
    );
    if (dashboard) dashboard.style.display = "";
    if (workspace) workspace.style.display = "none";
  },
} as const;

const BINDINGS = [
  {
    selector: '[data-role="tool-category-action"]',
    event: "click",
    handler: HANDLERS.seoAction,
    preventDefault: true,
  },
  {
    selector: '[data-role="tool-category-back"]',
    event: "click",
    handler: HANDLERS.seoBack,
    preventDefault: true,
  },
] as const;

export function buildSeoActions() {
  return defineRenderOnLoadActions({
    handlers: HANDLERS,
    bindings: [...BINDINGS],
    description: "Web & SEO workspace actions",
  });
}

/features/images/logic.ts:
export type ImageInspectionResult =
  | {
      success: boolean;
      output: string;
      message?: string;
    };

export interface DataUrlInspection {
  success: boolean;
  output: string;
  message?: string;
}

export interface SvgInspection {
  success: boolean;
  output: string;
  message?: string;
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function base64ToByteLength(base64: string): number {
  const clean = base64.replace(/[\r\n\s]/g, "");
  if (clean.length === 0) return 0;
  const padding = clean.endsWith("==") ? 2 : clean.endsWith("=") ? 1 : 0;
  return Math.floor((clean.length * 3) / 4) - padding;
}

function inferMimeFromExt(path: string): string {
  const m = path.match(/\.(svg|png|jpe?g|gif|webp|ico|bmp)$/i);
  if (m) {
    const ext = m[1].toLowerCase();
    switch (ext) {
      case "svg":
        return "image/svg+xml";
      case "png":
        return "image/png";
      case "jpg":
      case "jpeg":
        return "image/jpeg";
      case "gif":
        return "image/gif";
      case "webp":
        return "image/webp";
      case "ico":
        return "image/x-icon";
      case "bmp":
        return "image/bmp";
      default:
        return "application/octet-stream";
    }
  }
  return "application/octet-stream";
}

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(2)} KB`;
  return `${(n / (1024 * 1024)).toFixed(2)} MB`;
}

export function inspectDataUrl(input: string): DataUrlInspection {
  const trimmed = input.trim();
  if (!trimmed) {
    return { success: false, output: "", message: "Please enter a data URL or SVG." };
  }

  const m = trimmed.match(/^data:([^,]*),([\s\S]*)$/i);
  if (!m) {
    return {
      success: false,
      output: "",
      message: "Input is not a data URL (expected data:<mime>[;base64],<payload>).",
    };
  }
  const meta = m[1] || "";
  const payload = m[2];
  const isBase64 = /;base64/i.test(meta);
  const mimePart = meta.split(";")[0].trim() || "application/octet-stream";

  const lines: string[] = [];
  lines.push(`Type: ${mimePart}`);
  lines.push(`Encoding: ${isBase64 ? "base64" : "plain"}`);

  if (mimePart.toLowerCase() === "image/svg+xml") {
    const svg = payload;
    const widthMatch = svg.match(/<svg\b[^>]*\bwidth\s*=\s*["']([^"']+)["']/i);
    const heightMatch = svg.match(/<svg\b[^>]*\bheight\s*=\s*["']([^"']+)["']/i);
    const viewBoxMatch = svg.match(/<svg\b[^>]*\bviewBox\s*=\s*["']([^"']+)["']/i);
    let sizeText: string;
    if (widthMatch && heightMatch) {
      sizeText = `${widthMatch[1]} x ${heightMatch[1]}`;
    } else if (viewBoxMatch) {
      const vb = viewBoxMatch[1].trim().split(/\s+/).filter(Boolean);
      if (vb.length === 4) {
        sizeText = `${vb[2]} x ${vb[3]} (viewBox)`;
      } else {
        sizeText = "unknown (no width/height/viewBox)";
      }
    } else {
      sizeText = "unknown (no width/height/viewBox)";
    }
    lines.push(`Dimensions: ${sizeText}`);
  }

  const byteLength = isBase64
    ? base64ToByteLength(payload)
    : new Blob([payload]).size;
  lines.push(`Size: ${formatBytes(byteLength)} (${byteLength} bytes)`);
  lines.push(
    `Payload length: ${isBase64 ? payload.replace(/[\s]/g, "").length : payload.length} chars`
  );

  return { success: true, output: lines.join("\n") };
}

export function inspectSvgText(input: string): SvgInspection {
  const trimmed = input.trim();
  if (!trimmed) {
    return { success: false, output: "", message: "Please enter SVG markup." };
  }

  const svgOpen = trimmed.match(/<svg\b([^>]*)>/i);
  if (!svgOpen) {
    return {
      success: false,
      output: "",
      message: "Input does not contain a <svg> element.",
    };
  }
  const attrs = svgOpen[1] || "";
  const widthMatch = attrs.match(/\bwidth\s*=\s*["']([^"']+)["']/i);
  const heightMatch = attrs.match(/\bheight\s*=\s*["']([^"']+)["']/i);
  const viewBoxMatch = attrs.match(/\bviewBox\s*=\s*["']([^"']+)["']/i);

  let sizeText: string;
  if (widthMatch && heightMatch) {
    sizeText = `${widthMatch[1]} x ${heightMatch[1]}`;
  } else if (viewBoxMatch) {
    const vb = viewBoxMatch[1].trim().split(/\s+/).filter(Boolean);
    sizeText = vb.length === 4 ? `${vb[2]} x ${vb[3]} (viewBox)` : "unknown";
  } else {
    sizeText = "unknown";
  }

  const lines: string[] = [];
  lines.push("Type: image/svg+xml");
  lines.push(`Dimensions: ${sizeText}`);
  lines.push(`Size: ${formatBytes(trimmed.length)} (${trimmed.length} bytes)`);
  const pathCount = (trimmed.match(/<path\b/gi) || []).length;
  const rectCount = (trimmed.match(/<rect\b/gi) || []).length;
  const circleCount = (trimmed.match(/<circle\b/gi) || []).length;
  const textCount = (trimmed.match(/<text\b/gi) || []).length;
  lines.push(
    `Shapes: ${pathCount} path, ${rectCount} rect, ${circleCount} circle, ${textCount} text`
  );

  return { success: true, output: lines.join("\n") };
}

export function inspectImageInput(input: string): ImageInspectionResult {
  const trimmed = input.trim();
  if (!trimmed) {
    return { success: false, output: "", message: "Please enter a data URL or SVG markup." };
  }

  if (/^data:/i.test(trimmed)) {
    return inspectDataUrl(trimmed);
  }

  if (/<svg\b/i.test(trimmed)) {
    return inspectSvgText(trimmed);
  }

  const urlLike = trimmed.match(/^https?:\/\/\S+/i);
  if (urlLike) {
    return {
      success: false,
      output: "",
      message:
        "Remote URLs are not fetched. Paste the data URL or the raw SVG markup instead.",
    };
  }

  return {
    success: false,
    output: "",
    message: "No recognizable image input. Provide a data URL or SVG markup.",
  };
}

