/features/images/actions.ts:
import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";

const HANDLERS = {
  imagesAction: ({ document }: { document: Document }) => {
    const input = document.querySelector<HTMLTextAreaElement>(
      '[data-role="tool-category-input"]'
    );
    const result = document.querySelector<HTMLElement>(
      '[data-role="tool-category-result"]'
    );
    if (!input || !result) return;

    const text = input.value.trim();
    if (!text) {
      result.dataset.state = "error";
      result.textContent =
        "Please paste a data URL or SVG markup to inspect.";
      return;
    }

    let output = "";
    let success = true;
    let message = "";

    if (text.startsWith("data:image/")) {
      const headerEnd = text.indexOf(",");
      if (headerEnd === -1) {
        success = false;
        message = "Data URL is missing the comma separator.";
      } else {
        const header = text.slice(0, headerEnd);
        const body = text.slice(headerEnd + 1);
        const mimeMatch = header.match(/data:image\/([a-zA-Z0-9.+-]+)/i);
        const mime = mimeMatch ? mimeMatch[1].toLowerCase() : "unknown";
        const isBase64 = header.endsWith(";base64");
        const rawSize = isBase64
          ? Math.ceil((body.length * 3) / 4)
          : decodeURIComponent(body).length;

        const lines: string[] = [];
        lines.push(`Type: image/${mime}`);
        lines.push(`Encoding: ${isBase64 ? "base64" : "URL-encoded"}`);
        lines.push(`Size: ${rawSize} bytes`);

        if (mime === "svg" || mime === "svg+xml") {
          let svgText = body;
          if (isBase64) {
            try {
              svgText = decodeURIComponent(escape(atob(body)));
            } catch {
              svgText = "";
            }
          }
          const sizeMatch = svgText.match(
            /width\s*=\s*["']?(\d+)[\s"']?\s+height\s*=\s*["']?(\d+)/i
          );
          if (sizeMatch) {
            lines.push(`Dimensions: ${sizeMatch[1]} x ${sizeMatch[2]}`);
          }
        }
        output = lines.join("\n");
      }
    } else if (text.startsWith("<svg") || text.includes("<svg")) {
      const svgText = text;
      const lines: string[] = [];
      lines.push("Type: SVG markup");
      const sizeMatch = svgText.match(
        /width\s*=\s*["']?(\d+)[\s"']?\s+height\s*=\s*["']?(\d+)/i
      );
      if (sizeMatch) {
        lines.push(`Dimensions: ${sizeMatch[1]} x ${sizeMatch[2]}`);
      }
      lines.push(`Size: ${svgText.length} bytes`);
      output = lines.join("\n");
    } else {
      success = false;
      message =
        "Input does not look like a data URL or SVG markup. Start with 'data:image/...' or '<svg...'.";
    }

    if (success) {
      result.dataset.state = "success";
      result.textContent = output;
    } else {
      result.dataset.state = "error";
      result.textContent = message;
    }
  },
  imagesBack: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>(
      '[data-role="tool-dashboard"]'
    );
    const workspace = document.querySelector<HTMLElement>(
      '[data-role="tool-category-workspace"]'
    );
    if (dashboard) dashboard.style.display = "";
    if (workspace) workspace.style.display = "none";
  },
} as const;

const BINDINGS = [
  {
    selector: '[data-tool-category="images"] [data-role="tool-category-action"]',
    event: "click",
    handler: HANDLERS.imagesAction,
    preventDefault: true,
  },
  {
    selector: '[data-tool-category="images"] [data-role="tool-category-back"]',
    event: "click",
    handler: HANDLERS.imagesBack,
    preventDefault: true,
  },
] as const;

export function buildImagesActions() {
  return defineRenderOnLoadActions({
    handlers: HANDLERS,
    bindings: [...BINDINGS],
    description: "Images & Media workspace actions",
  });
}

/features/social/logic.ts:
export interface SocialPreviewFields {
  title: string;
  description: string;
  url: string;
}

export interface SocialPreviewResult {
  success: boolean;
  output: string;
  message?: string;
}

export function parseSocialFields(
  input: string
): { success: boolean; fields: SocialPreviewFields | null; message?: string } {
  const trimmed = input.trim();

  if (!trimmed) {
    return { success: false, fields: null, message: "Please enter title, description, and URL." };
  }

  // Try JSON object: {"title":"…","description":"…","url":"https://…"}
  if (trimmed.startsWith("{")) {
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (
        typeof parsed === "object" &&
        parsed !== null &&
        "title" in parsed &&
        "description" in parsed &&
        "url" in parsed
      ) {
        const obj = parsed as Record<string, unknown>;
        return {
          success: true,
          fields: {
            title: typeof obj.title === "string" ? obj.title : String(obj.title),
            description:
              typeof obj.description === "string" ? obj.description : String(obj.description),
            url: typeof obj.url === "string" ? obj.url : String(obj.url),
          },
        };
      }
    } catch {
      // Not valid JSON; fall through to text parsing
    }
  }

  // Try simple key: value lines (Title: …, Description: …, URL: …)
  const lines = trimmed.split(/\r?\n/);
  const fields: SocialPreviewFields = { title: "", description: "", url: "" };
  let foundTitle = false;
  let foundDescription = false;
  let foundUrl = false;

  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;

    const titleMatch = t.match(/^title\s*:\s*(.+)$/i);
    if (titleMatch) {
      fields.title = titleMatch[1].trim();
      foundTitle = true;
      continue;
    }

    const descMatch = t.match(/^description\s*:\s*(.+)$/i);
    if (descMatch) {
      fields.description = descMatch[1].trim();
      foundDescription = true;
      continue;
    }

    const urlMatch = t.match(/^url\s*:\s*(.+)$/i);
    if (urlMatch) {
      fields.url = urlMatch[1].trim();
      foundUrl = true;
      continue;
    }
  }

  // Try tab or pipe-separated: title | description | url
  if (!foundTitle && !foundDescription && !foundUrl) {
    const parts = trimmed.split(/\t|\|/).map((p) => p.trim());
    if (parts.length >= 3) {
      fields.title = parts[0];
      fields.description = parts[1];
      fields.url = parts[2];
      foundTitle = true;
      foundDescription = true;
      foundUrl = true;
    } else if (parts.length === 1) {
      // Single value: treat as title only
      fields.title = parts[0];
      foundTitle = true;
    }
  }

  if (!foundTitle) {
    return { success: false, fields: null, message: "Title is required. Use JSON, key: value lines, or tab/pipe-separated values." };
  }

  return { success: true, fields };
}

export function generateSocialPreview(fields: SocialPreviewFields): SocialPreviewResult {
  const title = fields.title.trim();
  const description = fields.description.trim();
  const url = fields.url.trim();

  if (!title) {
    return { success: false, output: "", message: "Title is required for a social preview." };
  }

  const lines: string[] = [];
  lines.push("=== Social Preview ===");
  lines.push("");
  lines.push(`Title: ${title}`);
  lines.push(`Title length: ${title.length} chars`);
  lines.push("");
  lines.push(`Description: ${description || "(none)"}`);
  lines.push(`Description length: ${description.length} chars`);
  lines.push("");
  lines.push(`URL: ${url || "(none)"}`);
  lines.push("");

  // Simple heuristic suggestions
  const suggestions: string[] = [];
  if (title.length > 60) {
    suggestions.push(`Title is ${title.length} chars. Most platforms truncate around 60-70 chars.`);
  }
  if (description.length > 200) {
    suggestions.push(`Description is ${description.length} chars. Many platforms truncate around 160-200 chars.`);
  }
  if (!url) {
    suggestions.push("No URL provided. A canonical URL is recommended for link previews.");
  }

  if (suggestions.length > 0) {
    lines.push("Suggestions:");
    for (const s of suggestions) {
      lines.push(`  • ${s}`);
    }
  } else {
    lines.push("Looks good — all fields within common platform limits.");
  }

  return { success: true, output: lines.join("\n") };
}

export function runSocialPreview(input: string): SocialPreviewResult {
  const parsed = parseSocialFields(input);
  if (!parsed.success || !parsed.fields) {
    return { success: false, output: "", message: parsed.message ?? "Invalid input." };
  }
  return generateSocialPreview(parsed.fields);
}

