import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";

const HANDLERS = {
  socialAction: ({ document }: { document: Document }) => {
    const input = document.querySelector<HTMLTextAreaElement>(
      '[data-tool-category="social"] [data-role="tool-category-input"]'
    );
    const result = document.querySelector<HTMLElement>(
      '[data-tool-category="social"] [data-role="tool-category-result"]'
    );
    if (!input || !result) return;

    const raw = input.value;
    if (!raw.trim()) {
      result.dataset.state = "error";
      result.textContent =
        "Please fill in the title, description, and URL fields (or paste a JSON object).";
      return;
    }

    // Try to parse as JSON object fallback
    let title = "";
    let description = "";
    let url = "";

    const trimmed = raw.trim();
    if (trimmed.startsWith("{")) {
      try {
        const obj = JSON.parse(trimmed) as Record<string, unknown>;
        title = typeof obj.title === "string" ? obj.title : "";
        description = typeof obj.description === "string" ? obj.description : "";
        url = typeof obj.url === "string" ? obj.url : "";
      } catch {
        result.dataset.state = "error";
        result.textContent =
          "Invalid JSON object. Expected {\"title\":\"…\",\"description\":\"…\",\"url\":\"https://…\"}.";
        return;
      }
    } else {
      // Read from named fields
      const titleField = document.querySelector<HTMLInputElement>(
        '[data-tool-category="social"] input[name="title"]'
      );
      const descField = document.querySelector<HTMLInputElement>(
        '[data-tool-category="social"] input[name="description"]'
      );
      const urlField = document.querySelector<HTMLInputElement>(
        '[data-tool-category="social"] input[name="url"]'
      );
      title = titleField ? titleField.value.trim() : "";
      description = descField ? descField.value.trim() : "";
      url = urlField ? urlField.value.trim() : "";
    }

    if (!title || !description || !url) {
      result.dataset.state = "error";
      result.textContent =
        "Title, description, and URL are all required for the social preview.";
      return;
    }

    // Build the social preview summary
    const titleDisplay =
      title.length > 60 ? title.slice(0, 57) + "…" : title;
    const descDisplay =
      description.length > 120 ? description.slice(0, 117) + "…" : description;

    const lines: string[] = [];
    lines.push("— Social Preview —");
    lines.push("");
    lines.push(`Title: ${titleDisplay}`);
    lines.push(`(${title.length} chars${title.length > 60 ? " — truncated for display" : ""})`);
    lines.push("");
    lines.push(`Description: ${descDisplay}`);
    lines.push(
      `(${description.length} chars${description.length > 120 ? " — truncated for display" : ""})`
    );
    lines.push("");
    lines.push(`URL: ${url}`);

    result.dataset.state = "success";
    result.textContent = lines.join("\n");
  },
  socialBack: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>(
      '[data-role="tool-dashboard"]'
    );
    const workspace = document.querySelector<HTMLElement>(
      '[data-tool-category="social"][data-role="tool-category-workspace"]'
    );
    if (dashboard) dashboard.style.display = "";
    if (workspace) workspace.style.display = "none";
  },
} as const;

const BINDINGS = [
  {
    selector: '[data-tool-category="social"] [data-role="tool-category-action"]',
    event: "click",
    handler: HANDLERS.socialAction,
    preventDefault: true,
  },
  {
    selector: '[data-tool-category="social"] [data-role="tool-category-back"]',
    event: "click",
    handler: HANDLERS.socialBack,
    preventDefault: true,
  },
] as const;

export function buildSocialActions() {
  return defineRenderOnLoadActions({
    handlers: HANDLERS,
    bindings: [...BINDINGS],
    description: "Social & Platforms workspace actions",
  });
}

