  jsonFormat: ({ document }: { document: Document }) => {
    const input = document.querySelector<HTMLTextAreaElement>(
      '[data-role="tool-json-input"]'
    );
    const result = document.querySelector<HTMLElement>(
      '[data-role="tool-json-result"]'
    );
    if (!input || !result) return;

    const text = input.value.trim();
    if (!text) {
      result.dataset.state = "error";
      result.textContent = "Please enter JSON to format.";
      return;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch (err) {
      const reason = err instanceof Error ? err.message : "Invalid JSON";
      result.dataset.state = "error";
      result.textContent = `Invalid JSON: ${reason}`;
      return;
    }

    result.dataset.state = "success";
    result.textContent = JSON.stringify(parsed, null, 2);
