export interface LibraryRenderOptions {
  dom: DOM;
  css: CssMap;
  libraryClass?: string;
  cardClass?: string;
}

export function renderLibrary(opts: LibraryRenderOptions): string {
  const { dom, css, libraryClass = "", cardClass = "" } = opts;

  const searchInput = dom.createElement(
    "input",
    {
      type: "text",
      class: "tool-search-input",
      placeholder: "Search tools…",
      "data-role": "tool-search",
      "aria-label": "Search tools",
    },
    ""
  );

  const openJsonBtn = dom.createElement(
    "button",
    {
      type: "button",
      class: "pure-button tool-lib-json-btn",
      "data-role": "tool-open-json",
    },
    "Open JSON Formatter"
  );

  const closeBtn = dom.createElement(
    "button",
    {
      type: "button",
      class: "tool-lib-close-btn",
      "data-role": "tool-library-close",
      "aria-label": "Close library",
    },
    "✕"
  );

  const categoryRows = [
    {
      key: "text",
      label: "Text & Content",
      icon: "Aa",
      color: "tool-cat-text",
    },
    {
      key: "data",
      label: "Development & Data",
      icon: "{}",
      color: "tool-cat-data",
    },
    {
      key: "seo",
      label: "Web & SEO",
      icon: "🌐",
      color: "tool-cat-seo",
    },
    {
      key: "images",
      label: "Images & Media",
      icon: "🖼",
      color: "tool-cat-images",
    },
    {
      key: "social",
      label: "Social & Platforms",
      icon: "🔗",
      color: "tool-cat-social",
    },
  ];

  const rowsHtml = categoryRows
    .map((row) => {
      const icon = dom.createElement(
        "span",
        { class: `tool-lib-icon ${row.color}` },
        row.icon
      );
      const label = dom.createElement(
        "span",
        { class: "tool-lib-label" },
        row.label
      );
      const btn = dom.createElement(
        "button",
        {
          type: "button",
          class: "tool-lib-row",
          "data-role": `tool-card-${row.key}`,
        },
        [icon, label]
      );
      return btn;
    })
    .join("\n");

  const header = dom.createElement(
    "div",
    { class: "tool-lib-header" },
    [
      dom.createElement("h2", { class: "tool-lib-title" }, "Tool Library"),
      closeBtn,
    ]
  );

  const searchSection = dom.createElement(
    "div",
    { class: "tool-lib-search" },
    [searchInput]
  );

  const quickAccess = dom.createElement(
    "div",
    { class: "tool-lib-quick-access" },
    [
      dom.createElement(
        "p",
        { class: "tool-lib-quick-label" },
        "Quick Access"
      ),
      openJsonBtn,
    ]
  );

  const categorySection = dom.createElement(
    "div",
    { class: "tool-lib-categories" },
    [dom.createElement("p", { class: "tool-lib-cat-label" }, "Categories"), rowsHtml]
  );

  const overlay = dom.createElement(
    "div",
    {
      class: `tool-library-overlay ${libraryClass}`,
      "data-role": "tool-library",
      "data-state": "closed",
    },
    [
      dom.createElement("div", { class: "tool-lib-backdrop" }),
      dom.createElement(
        "div",
        { class: `tool-lib-panel ${cardClass}` },
        [header, searchSection, quickAccess, categorySection]
      ),
    ]
  );

  return overlay;
}

/ui/space.ts:
import type { DOM } from "@anikitenko/fdo-sdk";

interface CssMap {
  [key: string]: Record<string, string>;
}

export interface SpaceRenderOptions {
  dom: DOM;
  css: CssMap;
}

interface FavouriteTool {
  name: string;
  description: string;
  category: string;
}

const FAVOURITE_TOOLS: readonly FavouriteTool[] = [
  {
    name: "JSON Formatter",
    description: "Beautify or minify JSON documents locally.",
    category: "Development",
  },
  {
    name: "Text Transformer",
    description: "Uppercase, lowercase, or title-case text.",
    category: "Text & Content",
  },
  {
    name: "SEO HTML Analyzer",
    description: "Inspect titles, headings, links, and image alt coverage.",
    category: "Web & SEO",
  },
  {
    name: "Social Preview",
    description: "Preview how title, description, and URL look on platforms.",
    category: "Social",
  },
] as const;

export function renderSpace(opts: SpaceRenderOptions): string {
  const { dom } = opts;

  const favouriteRows = FAVOURITE_TOOLS.map(
    (tool) =>
      `<li class="pure-g" data-favourite-tool="${tool.name}">` +
      `<span class="pure-u-1 favorite-row-name">${tool.name}</span>` +
      `<span class="pure-u-1 favorite-row-desc">${tool.description}</span>` +
      `<span class="pure-u-1 favorite-row-cat">${tool.category}</span>` +
      `</li>`
  ).join("");

  const favouriteSection =
    `<section class="space-section">` +
    `<h3>Favourite Tools</h3>` +
    `<ul class="space-favourites">` +
    favouriteRows +
    `</ul>` +
    `</section>`;

  const savedSection =
    `<section class="space-section">` +
    `<h3>Saved Inputs</h3>` +
    `<p class="space-empty-note">` +
    `No saved inputs yet. Results you generate are kept only in your browser session.` +
    `</p>` +
    `</section>`;

  const privacyNote =
    `<p class="space-privacy-note">` +
    `All processing happens locally in your browser. Nothing is uploaded, stored, or shared.` +
    `</p>`;

  return (
    `<div data-role="tool-space-dialog" data-state="closed" role="dialog" aria-modal="true" aria-label="Personal space">` +
    `<div class="space-backdrop"></div>` +
    `<div class="space-sheet">` +
    `<div class="space-header">` +
    `<h2>Personal Space</h2>` +
    `<button type="button" data-role="tool-space-close" class="pure-button space-close-btn" aria-label="Close personal space">&times;</button>` +
    `</div>` +
    `<div class="space-body">` +
    `<nav class="space-tabs" role="tablist">` +
    `<button type="button" class="pure-button space-tab active" role="tab" aria-selected="true">Favourites</button>` +
    `<button type="button" class="pure-button space-tab" role="tab" aria-selected="false">Saved</button>` +
    `</nav>` +
    favouriteSection +
    savedSection +
    `</div>` +
    `<footer class="space-footer">` +
    privacyNote +
    `</footer>` +
    `</div>` +
    `</div>`
  );
}

/ui/category-shell.ts:
import type { DOM } from "@anikitenko/fdo-sdk";

interface CssMap {
  [key: string]: Record<string, string>;
}

export interface CategoryShellRenderOptions {
  dom: DOM;
  css: CssMap;
  category: string;
  title: string;
  inputPlaceholder?: string;
  actionLabel?: string;
  shellClass?: string;
  inputClass?: string;
  actionClass?: string;
  resultClass?: string;
  backClass?: string;
  extraMarkup?: string;
}

export function renderCategoryShell(opts: CategoryShellRenderOptions): string {
  const {
    dom,
    category,
    title,
    inputPlaceholder,
    actionLabel,
    shellClass,
    inputClass,
    actionClass,
    resultClass,
    backClass,
    extraMarkup,
  } = opts;

  const placeholder = inputPlaceholder || "Enter input here...";
  const action = actionLabel || "Run";
  const shellCls = shellClass || "tool-category-shell";
  const inputCls = inputClass || "tool-category-input-area";
  const actionCls = actionClass || "tool-category-action-btn";
  const resultCls = resultClass || "tool-category-result-area";
  const backCls = backClass || "tool-category-back-btn";

  const header = dom.createElement(
    "div",
    { class: `${shellCls}-header` },
    [
      dom.createElement(
        "button",
        {
          type: "button",
          "data-role": "tool-category-back",
          class: backCls,
        },
        [dom.createElement("span", { class: "tool-category-back-icon" }, ["← Back"])]
      ),
      dom.createElement("h2", { class: `${shellCls}-title` }, [title]),
    ]
  );

  const inputBlock = dom.createElement(
    "div",
    { class: `${shellCls}-input-block` },
    [
      dom.createElement(
        "label",
        { class: `${shellCls}-label` },
        ["Input"]
      ),
      dom.createElement(
        "textarea",
        {
          "data-role": "tool-category-input",
          class: inputCls,
          placeholder: placeholder,
          rows: "6",
        },
        []
      ),
    ]
  );

  const actionBlock = dom.createElement(
    "div",
    { class: `${shellCls}-action-block` },
    [
      dom.createElement(
        "button",
        {
          type: "button",
          "data-role": "tool-category-action",
          class: `${actionCls} pure-button pure-button-primary`,
        },
        [dom.createElement("span", { class: `${shellCls}-action-label` }, [action])]
      ),
    ]
  );

  const resultBlock = dom.createElement(
    "div",
    { class: `${shellCls}-result-block` },
    [
      dom.createElement(
        "label",
        { class: `${shellCls}-label` },
        ["Result"]
      ),
      dom.createElement(
        "div",
        {
          "data-role": "tool-category-result",
          "data-state": "idle",
          class: resultCls,
        },
        [dom.createElement("span", { class: "tool-category-result-idle" }, ["Ready."])]
      ),
    ]
  );

  const inner = [header, inputBlock, actionBlock, resultBlock];
  if (extraMarkup) {
    inner.push(extraMarkup);
  }

  const shell = dom.createElement(
    "div",
    {
      "data-role": "tool-category-workspace",
      "data-tool-category": category,
      class: shellCls,
      style: "display:none;",
    },
    inner
  );

  return shell;
}

/styles/base.css:
/* base.css — shared visual foundation: palette variables, reset, typography,
   focus, motion keyframes and reduced-motion overrides.
   This file is imported by /styles.css before feature files, so it must not
   import other feature CSS. */

/* ---- Palette & scale variables ---- */
:root {
  --ww-bg: #0e2a2c;
  --ww-bg-soft: #14393c;
  --ww-bg-card: #1a4245;
  --ww-bg-dock: #0c2426;
  --ww-ivory: #f5f0e3;
  --ww-ivory-soft: #ece6d5;
  --ww-ink: #1c3134;
  --ww-ink-soft: #4a5f63;
  --ww-warm: #e8c98f;
  --ww-warm-soft: #d4b06a;
  --ww-line: rgba(245, 240, 227, 0.12);
  --ww-line-strong: rgba(245, 240, 227, 0.22);
  --ww-tile-text: #f0c8a0;
  --ww-tile-data: #a8c9b8;
  --ww-tile-seo: #a8c0d8;
  --ww-tile-images: #d0b0c8;
  --ww-tile-social: #d8b0a0;
  --ww-success: #5fb88c;
  --ww-error: #d08070;
  --ww-radius: 10px;
  --ww-radius-lg: 14px;
  --ww-shadow: 0 2px 10px rgba(0, 0, 0, 0.18);
  --ww-shadow-lg: 0 8px 28px rgba(0, 0, 0, 0.32);
  --ww-space-xs: 6px;
  --ww-space-sm: 10px;
  --ww-space-md: 16px;
  --ww-space-lg: 24px;
  --ww-space-xl: 36px;
  --ww-font: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
  --ww-mono: "JetBrains Mono", "SFMono-Regular", "Menlo", "Consolas", monospace;
}

/* ---- Reset & base ---- */
body {
  margin: 0;
  padding: 0;
  background: var(--ww-bg);
  color: var(--ww-ivory);
  font-family: var(--ww-font);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

/* ---- Typography helpers ---- */
.ww-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ww-warm);
  margin: 0 0 var(--ww-space-xs) 0;
}

.ww-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--ww-ivory);
  margin: 0 0 var(--ww-space-xs) 0;
}

.ww-subtitle {
  font-size: 13px;
  color: rgba(245, 240, 227, 0.7);
  margin: 0 0 var(--ww-space-md) 0;
}

.ww-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: rgba(245, 240, 227, 0.8);
  margin: 0 0 var(--ww-space-xs) 0;
}

.ww-mono {
  font-family: var(--ww-mono);
}

/* ---- Focus visibility ---- */
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--ww-warm);
  outline-offset: 2px;
}

/* ---- Motion ---- */
@keyframes ww-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes ww-slide-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.ww-anim-fade {
  animation: ww-fade-in 180ms ease-out;
}

.ww-anim-slide {
  animation: ww-slide-up 220ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .ww-anim-fade {
    animation: none;
  }
  .ww-anim-slide {
    animation: none;
  }
}

/styles/layout.css:
@import "./base.css";

/* Layout: shell, dashboard grid, dock, card */

.shell {
  background: var(--ww-bg, #0e1a1f);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  color: var(--ww-ivory, #f3ede0);
  font-family: var(--ww-font, system-ui, sans-serif);
}

.shell button {
  font-family: inherit;
}

/* ── Dashboard grid ─────────────────────────────────────────────── */

.dashboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ww-space-md, 14px);
  padding: var(--ww-space-md, 14px) var(--ww-space-lg, 20px);
  flex: 1;
  align-content: start;
}

@media (max-width: 700px) {
  .dashboard {
    grid-template-columns: 1fr;
  }
}

/* ── Cards (tiles, quick-access, category cards) ────────────────── */

.card {
  background: var(--ww-bg-card, #1a2c33);
  border: 1px solid var(--ww-line, #2a4048);
  border-radius: var(--ww-radius-lg, 14px);
  padding: var(--ww-space-md, 14px);
  display: flex;
  flex-direction: column;
  gap: var(--ww-space-xs, 6px);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}

.card:hover {
  border-color: var(--ww-line-strong, #3a5862);
  background: #1e3340;
}

.card:active {
  transform: scale(0.98);
}

/* Category tile accent stripes */
.card-tile-text {
  border-left: 4px solid var(--ww-tile-text, #c9a06c);
}
.card-tile-data {
  border-left: 4px solid var(--ww-tile-data, #7aa87a);
}
.card-tile-seo {
  border-left: 4px solid var(--ww-tile-seo, #8a9cc2);
}
.card-tile-images {
  border-left: 4px solid var(--ww-tile-images, #b088a8);
}
.card-tile-social {
  border-left: 4px solid var(--ww-tile-social, #c29a8a);
}

/* ── Dock / footer ──────────────────────────────────────────────── */

.dock {
  position: sticky;
  bottom: 0;
  border-top: 1px solid var(--ww-line, #2a4048);
  background: var(--ww-bg-dock, #0b1418);
  padding: var(--ww-space-sm, 10px) var(--ww-space-lg, 20px);
  display: flex;
  align-items: center;
  gap: var(--ww-space-sm, 10px);
  flex-shrink: 0;
}

.dock-left {
  flex: 1;
}

.dock-right {
  display: flex;
  gap: var(--ww-space-xs, 6px);
}

/* ── Brand row (top of dashboard) ───────────────────────────────── */

.brand-row {
  padding: var(--ww-space-sm, 10px) var(--ww-space-lg, 20px) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: var(--ww-space-xs, 6px);
}

.brand-icon {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: var(--ww-warm, #c9a06c);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ww-bg, #0e1a1f);
  font-weight: 700;
  font-size: 14px;
}

.brand-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--ww-ivory, #f3ede0);
  letter-spacing: 0.02em;
}

.brand-meta {
  display: flex;
  gap: var(--ww-space-xs, 6px);
}

.brand-pill {
  background: var(--ww-bg-card, #1a2c33);
  border: 1px solid var(--ww-line, #2a4048);
  border-radius: 6px;
  padding: 3px 10px;
  font-size: 11px;
  color: var(--ww-ink-soft, #a0b4bc);
  cursor: pointer;
  transition: border-color 0.15s;
}

.brand-pill:hover {
  border-color: var(--ww-line-strong, #3a5862);
}

/* ── Dashboard header (title + subtitle) ────────────────────────── */

.dash-header {
  padding: var(--ww-space-md, 14px) var(--ww-space-lg, 20px) 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dash-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--ww-ivory, #f3ede0);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.dash-subtitle {
  font-size: 13px;
  color: var(--ww-ink-soft, #a0b4bc);
  line-height: 1.45;
  max-width: 420px;
}

/* ── Quick-access section label ─────────────────────────────────── */

.quick-label {
  padding: var(--ww-space-sm, 10px) var(--ww-space-lg, 20px) 0;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ww-ink-soft, #a0b4bc);
}

/* ── Quick-access card variant ──────────────────────────────────── */

.quick-card {
  background: var(--ww-bg-card, #1a2c33);
  border: 1px solid var(--ww-line, #2a4048);
  border-radius: var(--ww-radius-lg, 14px);
  padding: var(--ww-space-md, 14px);
  display: flex;
  align-items: center;
  gap: var(--ww-space-sm, 10px);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  min-height: 64px;
}

.quick-card:hover {
  border-color: var(--ww-line-strong, #3a5862);
  background: #1e3340;
}

.quick-card:active {
  transform: scale(0.98);
}

.quick-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 18px;
}

.quick-icon-json {
  background: var(--ww-bg-card, #1a2c33);
  border: 1px solid var(--ww-line-strong, #3a5862);
  color: var(--ww-ivory, #f3ede0);
}

.quick-label-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.quick-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--ww-ivory, #f3ede0);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.quick-sub {
  font-size: 11px;
  color: var(--ww-ink-soft, #a0b4bc);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Category tile content ──────────────────────────────────────── */

.tile-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.tile-icon-text {
  background: var(--ww-tile-text, #c9a06c);
  color: #1a1208;
}
.tile-icon-data {
  background: var(--ww-tile-data, #7aa87a);
  color: #0d1a0d;
}
.tile-icon-seo {
  background: var(--ww-tile-seo, #8a9cc2);
  color: #0e1428;
}
.tile-icon-images {
  background: var(--ww-tile-images, #b088a8);
  color: #1a0e16;
}
.tile-icon-social {
  background: var(--ww-tile-social, #c29a8a);
  color: #1a1008;
}

.tile-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ww-ivory, #f3ede0);
  line-height: 1.3;
}

.tile-sub {
  font-size: 11px;
  color: var(--ww-ink-soft, #a0b4bc);
  line-height: 1.3;
}

/* ── Section spacing ────────────────────────────────────────────── */

.dash-section-gap {
  height: var(--ww-space-xs, 6px);
  flex-shrink: 0;
}

/* ── Reduced motion ─────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .card,
  .quick-card {
    transition: none;
  }
  .card:active,
  .quick-card:active {
    transform: none;
  }
}

