}

.workspace-heading {
  display: flex;
  flex-direction: column;
  gap: var(--ww-space-xs);
}

.workspace-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--ww-ink);
  margin: 0;
}

.workspace-subtitle {
  font-size: 0.85rem;
  color: var(--ww-ink-soft);
  margin: 0;
}

.workspace-form {
  display: flex;
  flex-direction: column;
  gap: var(--ww-space-md);
}

.workspace-input {
  width: 100%;
  min-height: 180px;
  resize: vertical;
  background: var(--ww-ivory-soft);
  color: var(--ww-ink);
  border: 1px solid var(--ww-line);
  border-radius: var(--ww-radius);
  padding: var(--ww-space-md);
  font-family: var(--ww-mono);
  font-size: 0.85rem;
  line-height: 1.5;
  transition: border-color 0.15s ease;
}

.workspace-input:focus {
  border-color: var(--ww-warm);
}

.workspace-actions {
  display: flex;
  align-items: center;
  gap: var(--ww-space-sm);
}

.result {
  width: 100%;
  min-height: 160px;
  background: var(--ww-ivory-soft);
  color: var(--ww-ink);
  border: 1px solid var(--ww-line);
  border-radius: var(--ww-radius);
  padding: var(--ww-space-md);
  font-family: var(--ww-mono);
  font-size: 0.85rem;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
  overflow: auto;
  max-height: 400px;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.result[data-state="ready"] {
  background: var(--ww-ivory-soft);
  border-color: var(--ww-line);
  color: var(--ww-ink-soft);
}

.result[data-state="success"] {
  background: #f2faf2;
  border-color: var(--ww-success);
  color: var(--ww-ink);
}

.result[data-state="error"] {
  background: #fdf3f1;
  border-color: var(--ww-error);
  color: var(--ww-ink);
}

.result-label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ww-ink-soft);
  margin-bottom: var(--ww-space-xs);
}

.result-header {
  display: flex;
  align-items: center;
  gap: var(--ww-space-xs);
  margin-bottom: var(--ww-space-xs);
}

.result-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ww-line-strong);
}

.result[data-state="success"] .result-status-dot {
  background: var(--ww-success);
}

.result[data-state="error"] .result-status-dot {
  background: var(--ww-error);
}

.result-message {
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: var(--ww-space-xs);
}

.result[data-state="success"] .result-message {
  color: var(--ww-success);
}

.result[data-state="error"] .result-message {
  color: var(--ww-error);
}

.workspace-result-body {
  white-space: pre-wrap;
  word-break: break-word;
}

.shell button {
  font-family: var(--ww-font);
}

/styles/panels.css:
@import "./base.css";

.library-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(10, 32, 41, 0.45);
  z-index: 90;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: var(--ww-space-lg);
  overflow-y: auto;
}

.library-backdrop[data-state="closed"] {
  display: none;
}

.library-backdrop[data-state="open"] {
  display: flex;
  animation: ww-fade-in 0.18s ease-out;
}

.library {
  background: #fbfaf6;
  border: 1px solid var(--ww-line-strong);
  border-radius: var(--ww-radius-lg);
  box-shadow: var(--ww-shadow-lg);
  width: 100%;
  max-width: 680px;
  padding: var(--ww-space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--ww-space-md);
}

.library-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ww-space-sm);
}

.library-title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--ww-ink);
  letter-spacing: -0.01em;
}

.library-close {
  width: 34px;
  height: 34px;
  border: 1px solid var(--ww-line-strong);
  border-radius: var(--ww-radius);
  background: #fff;
  color: var(--ww-ink-soft);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.library-close:hover {
  background: var(--ww-ivory-soft);
  color: var(--ww-ink);
}

.library-search {
  width: 100%;
  box-sizing: border-box;
  padding: 11px 14px;
  border: 1.5px solid var(--ww-line-strong);
  border-radius: var(--ww-radius);
  background: #fff;
  color: var(--ww-ink);
  font-size: 0.95rem;
}

.library-search:focus {
  outline: none;
  border-color: var(--ww-warm);
  box-shadow: 0 0 0 3px rgba(199, 158, 105, 0.25);
}

.library-search::placeholder {
  color: #9aa3a6;
}

.library-section-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ww-ink-soft);
  margin-bottom: 2px;
}

.library-category-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ww-space-sm);
}

.library-category-item {
  display: flex;
  align-items: center;
  gap: var(--ww-space-sm);
  padding: 12px 14px;
  border: 1px solid var(--ww-line);
  border-radius: var(--ww-radius);
  background: #fff;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ww-ink);
  text-align: left;
}

.library-category-item:hover {
  border-color: var(--ww-warm);
  background: var(--ww-ivory-soft);
}

.lib-cat-dot {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  flex-shrink: 0;
}

.lib-cat-dot-text { background: var(--ww-tile-text); }
.lib-cat-dot-data { background: var(--ww-tile-data); }
.lib-cat-dot-seo { background: var(--ww-tile-seo); }
.lib-cat-dot-images { background: var(--ww-tile-images); }
.lib-cat-dot-social { background: var(--ww-tile-social); }

.library-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ww-space-sm);
  padding: 10px 14px;
  border: 1px solid var(--ww-line);
  border-radius: var(--ww-radius);
  background: #fff;
  width: 100%;
  text-align: left;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ww-ink);
  cursor: pointer;
}

.library-row:hover {
  border-color: var(--ww-warm);
  background: var(--ww-ivory-soft);
}

.lib-row-hint {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--ww-ink-soft);
}

@media (max-width: 560px) {
  .library-backdrop {
    padding: var(--ww-space-sm);
    align-items: stretch;
  }
  .library-category-grid {
    grid-template-columns: 1fr;
  }
  .library {
    padding: var(--ww-space-md);
  }
}

/* ---- Personal space sheet ---- */

.space-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(8, 24, 32, 0.6);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--ww-space-lg);
  overflow-y: auto;
}

.space-backdrop[data-state="closed"] {
  display: none;
}

.space-backdrop[data-state="open"] {
  display: flex;
  animation: ww-fade-in 0.18s ease-out;
}

.space-dialog {
  background: #fbfaf6;
  border: 1px solid var(--ww-line-strong);
  border-radius: var(--ww-radius-lg);
  box-shadow: var(--ww-shadow-lg);
  width: 100%;
  max-width: 520px;
  max-height: calc(100vh - 2 * var(--ww-space-lg));
  overflow-y: auto;
  padding: var(--ww-space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--ww-space-md);
  animation: ww-slide-up 0.22s ease-out;
}

.space-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ww-space-sm);
}

.space-title {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--ww-ink);
}

.space-close {
  width: 34px;
  height: 34px;
  border: 1px solid var(--ww-line-strong);
  border-radius: var(--ww-radius);
  background: #fff;
  color: var(--ww-ink-soft);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.space-close:hover {
  background: var(--ww-ivory-soft);
  color: var(--ww-ink);
}

.space-tabs {
  display: flex;
  gap: var(--ww-space-xs);
  border-bottom: 1px solid var(--ww-line);
  padding-bottom: var(--ww-space-xs);
}

.space-tab {
  padding: 7px 14px;
  border: 1px solid transparent;
  border-radius: var(--ww-radius);
  background: transparent;
  color: var(--ww-ink-soft);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
}

.space-tab.active {
  background: var(--ww-ivory-soft);
  border-color: var(--ww-warm);
  color: var(--ww-ink);
}

.space-section-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ww-ink-soft);
}

.favourite-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ww-space-sm);
  padding: 11px 14px;
  border: 1px solid var(--ww-line);
  border-radius: var(--ww-radius);
  background: #fff;
}

.fav-name {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ww-ink);
}

.fav-hint {
  font-size: 0.78rem;
  color: var(--ww-ink-soft);
}

.fav-star {
  color: var(--ww-warm);
  font-size: 1rem;
}

.space-privacy {
  margin: 0;
  padding: var(--ww-space-sm) var(--ww-space-md);
  border: 1px dashed var(--ww-line-strong);
  border-radius: var(--ww-radius);
  background: var(--ww-ivory-soft);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--ww-ink-soft);
  text-align: center;
}

@media (max-width: 560px) {
  .space-backdrop {
    padding: var(--ww-space-sm);
  }
  .space-dialog {
    padding: var(--ww-space-md);
    max-height: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .space-dialog {
    animation: none;
  }
}

/ui/actions.ts:
import { defineRenderOnLoadActions, RenderOnLoadModule } from "@anikitenko/fdo-sdk";
import { buildJsonActions } from "./json-actions";
import { buildTextActions } from "../features/text/actions";
import { buildDataActions } from "../features/data/actions";
import { buildSeoActions } from "../features/seo/actions";
import { buildImagesActions } from "../features/images/actions";
import { buildSocialActions } from "../features/social/actions";

const DASHBOARD_HANDLERS = {
  openJson: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-role="tool-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openText: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-tool-category="text"][data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openData: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-tool-category="data"][data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openSeo: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-tool-category="seo"][data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openImages: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-tool-category="images"][data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openSocial: ({ document }: { document: Document }) => {
    const dashboard = document.querySelector<HTMLElement>('[data-role="tool-dashboard"]');
    const workspace = document.querySelector<HTMLElement>('[data-tool-category="social"][data-role="tool-category-workspace"]');
    if (dashboard) dashboard.style.display = "none";
    if (workspace) workspace.style.display = "";
  },
  openLibrary: ({ document }: { document: Document }) => {
    const library = document.querySelector<HTMLElement>('[data-role="tool-library"]');
    if (library) library.dataset.state = "open";
  },
  openSpace: ({ document }: { document: Document }) => {
    const space = document.querySelector<HTMLElement>('[data-role="tool-space-dialog"]');
    const backdrop = space?.parentElement;
    if (space) space.dataset.state = "open";
    if (backdrop) backdrop.dataset.state = "open";
  },
  closeLibrary: ({ document }: { document: Document }) => {
    const library = document.querySelector<HTMLElement>('[data-role="tool-library"]');
    if (library) library.dataset.state = "closed";
  },
  closeSpace: ({ document }: { document: Document }) => {
    const space = document.querySelector<HTMLElement>('[data-role="tool-space-dialog"]');
    const backdrop = space?.parentElement;
    if (space) space.dataset.state = "closed";
    if (backdrop) backdrop.dataset.state = "closed";
  },
} as const;

const DASHBOARD_BINDINGS = [
  { selector: '[data-role="tool-card-json"]', event: "click", handler: DASHBOARD_HANDLERS.openJson, preventDefault: true },
  { selector: '[data-role="tool-open-json"]', event: "click", handler: DASHBOARD_HANDLERS.openJson, preventDefault: true },
  { selector: '[data-role="tool-card-text"]', event: "click", handler: DASHBOARD_HANDLERS.openText, preventDefault: true },
  { selector: '[data-role="tool-card-data"]', event: "click", handler: DASHBOARD_HANDLERS.openData, preventDefault: true },
  { selector: '[data-role="tool-card-seo"]', event: "click", handler: DASHBOARD_HANDLERS.openSeo, preventDefault: true },
  { selector: '[data-role="tool-card-images"]', event: "click", handler: DASHBOARD_HANDLERS.openImages, preventDefault: true },
  { selector: '[data-role="tool-card-social"]', event: "click", handler: DASHBOARD_HANDLERS.openSocial, preventDefault: true },
  { selector: '[data-role="tool-library-button"]', event: "click", handler: DASHBOARD_HANDLERS.openLibrary, preventDefault: true },
  { selector: '[data-role="tool-space-button"]', event: "click", handler: DASHBOARD_HANDLERS.openSpace, preventDefault: true },
  { selector: '[data-role="tool-library-close"]', event: "click", handler: DASHBOARD_HANDLERS.closeLibrary, preventDefault: true },
  { selector: '[data-role="tool-space-close"]', event: "click", handler: DASHBOARD_HANDLERS.closeSpace, preventDefault: true },
] as const;

function dashboardActions() {
  return defineRenderOnLoadActions({
    handlers: DASHBOARD_HANDLERS,
    bindings: [...DASHBOARD_BINDINGS],
    description: "Dashboard, library, and space navigation",
  });
}

export function buildRenderOnLoadActions(): RenderOnLoadModule {
  const dashboard = dashboardActions();
  const json = buildJsonActions();
  const text = buildTextActions();
  const data = buildDataActions();
  const seo = buildSeoActions();
  const images = buildImagesActions();
  const social = buildSocialActions();

  const allSources: string[] = [];
  for (const mod of [dashboard, json, text, data, seo, images, social]) {
    const src = typeof mod.source === "string"
      ? mod.source
      : String(mod.source);
    allSources.push(src);
  }

  return {
    source: allSources.join("\n;\n"),
    language: "javascript",
    description: "Web Tools Workbench — all declarative actions",
  };
}
